
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Uts46Status {
    Valid,
    Disallowed,
    Mapped(&'static [u32]),
    Ignored,
    Deviation(&'static [u32]),
    DisallowedStd3Valid,
    DisallowedStd3Mapped(&'static [u32]),
}

#[derive(Debug, Clone, Copy)]
struct Row {
    start: u32,
    end: u32,
    status: EncodedStatus,
    mapping: u16,
}

#[derive(Debug, Clone, Copy)]
#[allow(dead_code)]
enum EncodedStatus {
    Valid,
    Disallowed,
    Mapped,
    Ignored,
    Deviation,
    DisallowedStd3Valid,
    DisallowedStd3Mapped,
}

pub const ROW_COUNT: usize = ROWS.len();
pub const COVERED_CODE_POINTS: u32 = 1_114_112;

pub fn uts46_status(cp: u32) -> Uts46Status {
    let mut lo = 0usize;
    let mut hi = ROWS.len();
    while lo < hi {
        let mid = lo + ((hi - lo) / 2);
        let row = ROWS[mid];
        if cp < row.start {
            hi = mid;
        } else if cp > row.end {
            lo = mid + 1;
        } else {
            return decode(row.status, row.mapping);
        }
    }
    Uts46Status::Disallowed
}

fn decode(status: EncodedStatus, mapping_idx: u16) -> Uts46Status {
    let m = mapping(mapping_idx);
    match status {
        EncodedStatus::Valid => Uts46Status::Valid,
        EncodedStatus::Disallowed => Uts46Status::Disallowed,
        EncodedStatus::Mapped => Uts46Status::Mapped(m),
        EncodedStatus::Ignored => Uts46Status::Ignored,
        EncodedStatus::Deviation => Uts46Status::Deviation(m),
        EncodedStatus::DisallowedStd3Valid => Uts46Status::DisallowedStd3Valid,
        EncodedStatus::DisallowedStd3Mapped => Uts46Status::DisallowedStd3Mapped(m),
    }
}

