#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn covers_unicode_code_space() {
        let covered: u32 = ROWS.iter().map(|r| r.end - r.start + 1).sum();
        assert_eq!(ROW_COUNT, 9_262);
        assert_eq!(covered, COVERED_CODE_POINTS);
    }

    #[test]
    fn canonical_kat_rows() {
        assert_eq!(uts46_status(0x0061), Uts46Status::Valid);
        assert_eq!(uts46_status(0x0041), Uts46Status::Mapped(&[0x0061]));
        assert_eq!(uts46_status(0x00AD), Uts46Status::Ignored);
        assert_eq!(uts46_status(0x00A0), Uts46Status::Mapped(&[0x0020]));
        assert_eq!(
            uts46_status(0x00DF),
            Uts46Status::Deviation(&[0x0073, 0x0073])
        );
        assert_eq!(uts46_status(0x03C2), Uts46Status::Deviation(&[0x03C3]));
        assert_eq!(uts46_status(0x200C), Uts46Status::Deviation(&[]));
        assert_eq!(uts46_status(0xE0001), Uts46Status::Disallowed);
        assert_eq!(uts46_status(0xE0100), Uts46Status::Ignored);
    }
}
